CREATE TABLE `material_metadata_enrichments` (
	`id` text PRIMARY KEY NOT NULL,
	`batch_id` text NOT NULL,
	`material_id` text NOT NULL,
	`field` text NOT NULL,
	`value` text NOT NULL,
	`normalized_value` text NOT NULL,
	`confidence` text NOT NULL,
	`source_provider` text NOT NULL,
	`source_url` text DEFAULT '' NOT NULL,
	`source_title` text DEFAULT '' NOT NULL,
	`reason_code` text NOT NULL,
	`material_fingerprint` text NOT NULL,
	`expected_title` text NOT NULL,
	`expected_author` text DEFAULT '' NOT NULL,
	`expected_publication_year` integer,
	`expected_isbn` text DEFAULT '' NOT NULL,
	`expected_publisher` text DEFAULT '' NOT NULL,
	`applied` integer DEFAULT false NOT NULL,
	`applied_at` text,
	`created_at` text NOT NULL,
	FOREIGN KEY (`material_id`) REFERENCES `materials`(`id`) ON UPDATE cascade ON DELETE restrict,
	CONSTRAINT "material_metadata_enrichments_field_valid" CHECK("material_metadata_enrichments"."field" in ('isbn', 'publisher')),
	CONSTRAINT "material_metadata_enrichments_confidence_valid" CHECK("material_metadata_enrichments"."confidence" in ('exact', 'probable', 'doubtful')),
	CONSTRAINT "material_metadata_enrichments_value_not_blank" CHECK(length(trim("material_metadata_enrichments"."value")) > 0),
	CONSTRAINT "material_metadata_enrichments_normalized_not_blank" CHECK(length(trim("material_metadata_enrichments"."normalized_value")) > 0),
	CONSTRAINT "material_metadata_enrichments_source_not_blank" CHECK(length(trim("material_metadata_enrichments"."source_provider")) > 0),
	CONSTRAINT "material_metadata_enrichments_reason_not_blank" CHECK(length(trim("material_metadata_enrichments"."reason_code")) > 0),
	CONSTRAINT "material_metadata_enrichments_fingerprint_valid" CHECK(length("material_metadata_enrichments"."material_fingerprint") = 64 and lower("material_metadata_enrichments"."material_fingerprint") not glob '*[^0-9a-f]*'),
	CONSTRAINT "material_metadata_enrichments_title_not_blank" CHECK(length(trim("material_metadata_enrichments"."expected_title")) > 0),
	CONSTRAINT "material_metadata_enrichments_year_valid" CHECK("material_metadata_enrichments"."expected_publication_year" is null or "material_metadata_enrichments"."expected_publication_year" between 1000 and 3000),
	CONSTRAINT "material_metadata_enrichments_source_url_valid" CHECK("material_metadata_enrichments"."source_url" = '' or "material_metadata_enrichments"."source_url" glob 'https://*'),
	CONSTRAINT "material_metadata_enrichments_applied_consistent" CHECK(("material_metadata_enrichments"."applied" = 0 and "material_metadata_enrichments"."applied_at" is null) or ("material_metadata_enrichments"."applied" = 1 and "material_metadata_enrichments"."applied_at" is not null))
);
--> statement-breakpoint
CREATE UNIQUE INDEX `idx_material_metadata_enrichments_batch_material_field` ON `material_metadata_enrichments` (`batch_id`,`material_id`,`field`);--> statement-breakpoint
CREATE INDEX `idx_material_metadata_enrichments_material_created` ON `material_metadata_enrichments` (`material_id`,`created_at`);--> statement-breakpoint
CREATE INDEX `idx_material_metadata_enrichments_batch_applied` ON `material_metadata_enrichments` (`batch_id`,`applied`);
--> statement-breakpoint
