INSERT INTO material_metadata_enrichments (id,batch_id,material_id,field,value,normalized_value,confidence,source_provider,source_url,source_title,reason_code,material_fingerprint,expected_title,expected_author,expected_publication_year,expected_isbn,expected_publisher,applied,applied_at,created_at)
SELECT id,batch_id,material_id,field,value,normalized_value,confidence,source_provider,source_url,source_title,reason_code,material_fingerprint,expected_title,expected_author,expected_publication_year,expected_isbn,expected_publisher,applied,applied_at,created_at FROM staged
WHERE EXISTS (SELECT 1 FROM materials m WHERE m.id = staged.material_id);
--> statement-breakpoint
UPDATE materials AS m
SET isbn = CASE WHEN trim(m.isbn) = '' THEN COALESCE((SELECT e.value FROM material_metadata_enrichments e
    WHERE e.batch_id = 'catalog-metadata-20260829-db50bcdc403a'
      AND e.material_id = m.id
      AND e.expected_title = m.title
      AND e.expected_author = m.author
      AND e.expected_publication_year IS m.publication_year
      AND e.expected_isbn = m.isbn
      AND e.expected_publisher = m.publisher AND e.field = 'isbn' LIMIT 1), m.isbn) ELSE m.isbn END,
    isbn_normalized = CASE WHEN trim(m.isbn) = '' THEN COALESCE((SELECT e.normalized_value FROM material_metadata_enrichments e
    WHERE e.batch_id = 'catalog-metadata-20260829-db50bcdc403a'
      AND e.material_id = m.id
      AND e.expected_title = m.title
      AND e.expected_author = m.author
      AND e.expected_publication_year IS m.publication_year
      AND e.expected_isbn = m.isbn
      AND e.expected_publisher = m.publisher AND e.field = 'isbn' LIMIT 1), m.isbn_normalized) ELSE m.isbn_normalized END,
    publisher = CASE WHEN trim(m.publisher) = '' THEN COALESCE((SELECT e.value FROM material_metadata_enrichments e
    WHERE e.batch_id = 'catalog-metadata-20260829-db50bcdc403a'
      AND e.material_id = m.id
      AND e.expected_title = m.title
      AND e.expected_author = m.author
      AND e.expected_publication_year IS m.publication_year
      AND e.expected_isbn = m.isbn
      AND e.expected_publisher = m.publisher AND e.field = 'publisher' LIMIT 1), m.publisher) ELSE m.publisher END,
    search_text = trim(m.search_text || ' ' || COALESCE((
      SELECT group_concat(e.normalized_value, ' ')
      FROM material_metadata_enrichments e
      WHERE (e.batch_id = 'catalog-metadata-20260829-db50bcdc403a'
      AND e.material_id = m.id
      AND e.expected_title = m.title
      AND e.expected_author = m.author
      AND e.expected_publication_year IS m.publication_year
      AND e.expected_isbn = m.isbn
      AND e.expected_publisher = m.publisher)
      AND ((e.field = 'isbn' AND trim(m.isbn) = '') OR (e.field = 'publisher' AND trim(m.publisher) = ''))
    ), '')),
    version = m.version + 1,
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
WHERE m.status = 'active'
  AND m.archived_at IS NULL
  AND EXISTS (SELECT 1 FROM material_metadata_enrichments e WHERE (e.batch_id = 'catalog-metadata-20260829-db50bcdc403a'
      AND e.material_id = m.id
      AND e.expected_title = m.title
      AND e.expected_author = m.author
      AND e.expected_publication_year IS m.publication_year
      AND e.expected_isbn = m.isbn
      AND e.expected_publisher = m.publisher)
      AND ((e.field = 'isbn' AND trim(m.isbn) = '') OR (e.field = 'publisher' AND trim(m.publisher) = '')));
--> statement-breakpoint
UPDATE material_metadata_enrichments AS e
SET applied = 1,
    applied_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
WHERE e.batch_id = 'catalog-metadata-20260829-db50bcdc403a'
  AND EXISTS (
    SELECT 1 FROM materials m
    WHERE m.id = e.material_id
      AND m.status = 'active'
      AND m.archived_at IS NULL
      AND m.title = e.expected_title
      AND m.author = e.expected_author
      AND m.publication_year IS e.expected_publication_year
      AND ((e.field = 'isbn' AND m.isbn = e.value) OR (e.field = 'publisher' AND m.publisher = e.value))
  );
--> statement-breakpoint
